/**
 * Confluence Node - Version 1 - Zod Schema Factory
 * Exports a factory that unions all discriminator schemas.
 *
 * Schema helpers (z, expressionSchema, etc.) are passed as parameters
 * by the schema-validator, not imported from external files.
 *
 * @generated - CommonJS JavaScript for runtime loading
 */

const getAttachmentSchema = require('./resource_attachment/index.schema');
const getPageSchema = require('./resource_page/index.schema');
const getSearchSchema = require('./resource_search/index.schema');
const getSpaceSchema = require('./resource_space/index.schema');

module.exports = function getSchema(helpers) {
  const { parameters, z } = helpers;
  // Apply discriminator default if not set
  const effectiveParams = parameters.resource === undefined ? { ...parameters, resource: 'page' } : parameters;
  return z.union([
    getAttachmentSchema({ ...helpers, parameters: effectiveParams }),
    getPageSchema({ ...helpers, parameters: effectiveParams }),
    getSearchSchema({ ...helpers, parameters: effectiveParams }),
    getSpaceSchema({ ...helpers, parameters: effectiveParams }),
  ]);
};